import { useEffect, useRef, useState } from 'react';
import { Client } from '@stomp/stompjs';

export const useWebSocket = (phone) => {
    const [isConnected, setIsConnected] = useState(false);
    const [messages, setMessages] = useState([]);
    const clientRef = useRef(null);

    useEffect(() => {
        if (!phone) return;

        // RabbitMQ Web STOMP usually runs on port 15674
        const client = new Client({
            brokerURL: 'ws://localhost:15674/ws',
            connectHeaders: {
                login: 'guest',
                passcode: 'guest',
            },
            reconnectDelay: 5000,
            heartbeatIncoming: 4000,
            heartbeatOutgoing: 4000,
        });

        client.onConnect = () => {
            setIsConnected(true);
            console.log('STOMP: Connected');

            // Subscribe to nearby updates queue or topic
            client.subscribe(`/exchange/penzi_events/v1.penzi.location.updated`, (message) => {
                if (message.body) {
                    setMessages((prev) => [...prev, JSON.parse(message.body)]);
                    // In a real app, trigger a re-fetch of nearby users here
                }
            });
        };

        client.onStompError = (frame) => {
            console.error('STOMP: Broker reported error: ' + frame.headers['message']);
            console.error('STOMP: Additional details: ' + frame.body);
        };

        client.activate();
        clientRef.current = client;

        return () => {
            if (clientRef.current) {
                clientRef.current.deactivate();
            }
        };
    }, [phone]);

    return { isConnected, messages };
};
